<template>
  <section class="w-full h-full flex flex-col">
    <div class="flex justify-end">
      <NuxtLink :to="{ name: 'login' }">
        <Button variant="secondary" size="sm">Log In</Button>
      </NuxtLink>
    </div>
    <div class="p-6 flex flex-col flex-auto justify-center self-center gap-6 w-full max-w-[552px] max-lg:px-0">
      <h1 class="font-semibold text-2xl leading-6">Reset account password</h1>
      <form v-if="!isPasswordReset" class="self-center flex flex-col gap-4 w-full justify-center" @submit="onSubmit">
        <p class="text-sm leading-5 text-muted-foreground">Enter a new password</p>
        <FormItemWrapper label="Password" name="password">
          <template #default="{ slots }">
            <KitFormPasswordInput
              id="password"
              placeholder="Enter your password"
              :component-field="slots.componentField"
              :disabled="isSettingPassword"
              autocomplete="password"
            />
          </template>
        </FormItemWrapper>
        <FormItemWrapper label="Confirm Password" name="confirm_password">
          <template #default="{ slots }">
            <KitFormPasswordInput
              id="confirm_password"
              placeholder="Confirm your password"
              :component-field="slots.componentField"
              :disabled="isSettingPassword"
              autocomplete="confirm-password"
            />
          </template>
        </FormItemWrapper>
        <Button variant="default" class="w-full" size="lg" :loading="isSettingPassword" type="submit"
          >Reset Password</Button
        >
      </form>
      <template v-else>
        <Alert variant="success">
          <CheckIcon />
          <AlertTitle>Your password has been changed successfully.</AlertTitle>
          <AlertDescription>You can log in with your new password.</AlertDescription>
        </Alert>
        <NuxtLink :to="{ name: 'login' }" class="mx-auto">
          <Button variant="default" size="lg">Log In</Button>
        </NuxtLink>
      </template>
    </div>
  </section>
</template>

<script setup lang="ts">
import * as z from 'zod';
import { toTypedSchema } from '@vee-validate/zod';
import { useForm } from 'vee-validate';
import { CheckIcon } from 'lucide-vue-next';
import { passwordRegex } from '~/constants/regularExpressions';

//TODO mb generated link on backend should be /password/reset/user_id?code=code ?

useSeoMeta({
  title: 'Reset password',
  description: 'Secure password reset page with strength validation to set a new password and regain access.',
});

definePageMeta({
  layout: 'login',
  auth: {
    unauthenticatedOnly: true,
    navigateAuthenticatedTo: '/projects',
  },
});

const isPasswordReset = ref<boolean>(false);

const { setPassword, isSettingPassword } = useSetPassword();

const formSchema = toTypedSchema(
  z
    .object({
      password: z.string({ message: 'Password is required' }).regex(passwordRegex, {
        message:
          'Password must contain at least 8 characters, with upper and lowercase letters, a number, a special symbol (#?!@$%^&*-), and no spaces',
      }),
      confirm_password: z
        .string({ message: 'Confirmation password is required' })
        .trim()
        .nonempty({ message: 'Confirmation password must be non-empty' }),
    })
    .refine((data) => data.password === data.confirm_password, {
      message: 'Passwords must match',
      path: ['confirm_password'],
    })
);

const { handleSubmit } = useForm({
  validationSchema: formSchema,
});

const onSubmit = handleSubmit(async (values) => {
  const query = useRoute().query;
  const code = query.code as string;
  const user_id = query.user_id as string;
  const requestBody = {
    otp_code: code,
    user_id: user_id,
    password: values.password,
  };
  await setPassword(requestBody)
    .then(() => {
      isPasswordReset.value = true;
    })
    .catch((error) => {
      console.error('Error sending reset password email:', error);
    });
});
</script>

<style scoped lang="scss"></style>
