import { accountPasswordSet } from '~/client';
import type { SetPasswordRequest, SetPasswordResponse } from '~/client';
import { showToastError, showToastSuccess } from '~/utils/show-toast';

export const useSetPassword = defineMutation(() => {
  const { mutateAsync: setPasswordMutation, asyncStatus } = useMutation({
    mutation: (form: SetPasswordRequest): Promise<SetPasswordResponse> =>
      accountPasswordSet({
        composable: '$fetch',
        body: form,
      }),
    onError: (error) => {
      showToastError(error);
    },
  });

  return {
    setPassword: setPasswordMutation,
    isSettingPassword: computed(() => asyncStatus.value === 'loading'),
  };
});
